using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class SharedYachtPortAtlas {
const string D="Assets/Scenes/Oasis/YachtPortAtlas";static Material shared;static int converted;static SharedYachtPortAtlas(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("SharedYachtPortAtlas.request"))return;try{File.Delete("SharedYachtPortAtlas.request");}catch(IOException){return;}Run();}
static int Tile(Material mat){string name=mat.name.ToLower();return name.Contains("orange")||name.Contains("globes")?-1:name.Contains("rope")?3:name.Contains("metal")?2:name.Contains("foundation")?1:0;}
static Mesh Convert(Mesh source,Material material,string path){var data=typeof(FinalPNGCityDetails).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{source});var p=(Vector3[])data.GetType().GetField("p").GetValue(data);var n=(Vector3[])data.GetType().GetField("normal").GetValue(data);var ids=(int[])data.GetType().GetField("ids").GetValue(data);var mesh=new Mesh{name=source.name+" shared port atlas",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.vertices=p;mesh.normals=n;mesh.triangles=ids;int tile=Tile(material);var uv=p.Select((v,i)=>Mathf.Abs(n[i].y)>.5f?new Vector2(v.x*.5f,v.z*.5f):Mathf.Abs(n[i].x)>Mathf.Abs(n[i].z)?new Vector2(v.z*.5f,v.y*.5f):new Vector2(v.x*.5f,v.y*.5f)).ToList();mesh.SetUVs(0,uv);mesh.SetUVs(1,p.Select(v=>new Vector4(tile,material.name.Contains("globes")?.8f:0,0,0)).ToList());Color tint=tile>=0?Color.white:material.GetColor("_BaseColor");mesh.SetColors(p.Select(v=>tint).ToList());mesh.RecalculateBounds();if(!mesh.vertices.SequenceEqual(p)||!mesh.triangles.SequenceEqual(ids))throw new Exception("Geometry changed");AssetDatabase.CreateAsset(mesh,path);converted++;return mesh;}
static Renderer Merge(GameObject parent,IEnumerable<MeshFilter> filters,string name,string path){var list=filters.ToArray();var mesh=new Mesh{name=name,indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.CombineMeshes(list.Select(f=>new CombineInstance{mesh=f.sharedMesh,transform=parent.transform.worldToLocalMatrix*f.transform.localToWorldMatrix}).ToArray(),true,true);AssetDatabase.CreateAsset(mesh,path);var g=new GameObject(name);g.transform.SetParent(parent.transform,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;var r=g.AddComponent<MeshRenderer>();r.sharedMaterial=shared;foreach(var f in list)UnityEngine.Object.DestroyImmediate(f.gameObject);return r;}
static void Run(){try{Directory.CreateDirectory(D+"/Meshes");string texturePath=D+"/Shared Yacht Yard Atlas.png";var importer=(TextureImporter)AssetImporter.GetAtPath(texturePath);importer.npotScale=TextureImporterNPOTScale.None;importer.mipmapEnabled=true;importer.streamingMipmaps=true;importer.anisoLevel=4;importer.wrapMode=TextureWrapMode.Clamp;importer.maxTextureSize=2048;foreach(var platform in new[]{"Android","iPhone"})importer.SetPlatformTextureSettings(new TextureImporterPlatformSettings{name=platform,overridden=true,maxTextureSize=2048,format=TextureImporterFormat.ASTC_6x6,compressionQuality=90});importer.SaveAndReimport();shared=new Material(AssetDatabase.LoadAssetAtPath<Shader>(D+"/MobileSharedYachtAtlas.shader")){name="Shared Yacht Yard Atlas",enableInstancing=true};shared.SetTexture("_Atlas",AssetDatabase.LoadAssetAtPath<Texture2D>(texturePath));AssetDatabase.CreateAsset(shared,D+"/Shared Yacht Yard Atlas.mat");var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var roads=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var yard=roads.GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="Yatch_Port");var original=yard.sharedMesh;var yardMesh=Convert(original,yard.GetComponent<MeshRenderer>().sharedMaterial,D+"/Meshes/Yatch Port Preserved Geometry.asset");yard.sharedMesh=yardMesh;yard.GetComponent<MeshRenderer>().sharedMaterial=shared;PrefabUtility.RecordPrefabInstancePropertyModifications(yard);PrefabUtility.RecordPrefabInstancePropertyModifications(yard.GetComponent<MeshRenderer>());var roadPrefab=PrefabUtility.LoadPrefabContents("Assets/Scenes/Oasis/FinalEnvironmentRoads/Final Roads.prefab");var target=roadPrefab.transform.Find(AnimationUtility.CalculateTransformPath(yard.transform,roads.transform));target.GetComponent<MeshFilter>().sharedMesh=yardMesh;target.GetComponent<MeshRenderer>().sharedMaterial=shared;PrefabUtility.SaveAsPrefabAsset(roadPrefab,"Assets/Scenes/Oasis/FinalEnvironmentRoads/Final Roads.prefab");PrefabUtility.UnloadPrefabContents(roadPrefab);
for(int index=1;index<=6;index++){string path="Assets/Scenes/Oasis/SouthBeach/Docking Pier "+index+".prefab";var prefab=PrefabUtility.LoadPrefabContents(path);var all=prefab.GetComponentsInChildren<MeshFilter>().ToArray();int part=0;foreach(var f in all){var r=f.GetComponent<MeshRenderer>();f.sharedMesh=Convert(f.sharedMesh,r.sharedMaterial,D+"/Meshes/Pier "+index+" Part "+part+++".asset");r.sharedMaterial=shared;}var detail=prefab.transform.Find("Reference dock details");var near=Merge(detail.gameObject,detail.GetComponentsInChildren<MeshFilter>(),"Shared atlas dock details",D+"/Meshes/Pier "+index+" Batched Details.asset");var basis=prefab.GetComponentsInChildren<MeshFilter>().Where(f=>!f.transform.IsChildOf(detail)).ToArray();foreach(var f in basis){foreach(var col in f.GetComponents<BoxCollider>()){var copy=prefab.AddComponent<BoxCollider>();copy.center=col.center;copy.size=col.size;}}var far=Merge(prefab,basis,"Shared atlas deck and foundation",D+"/Meshes/Pier "+index+" Batched Structure.asset");var lod=prefab.GetComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.10f,new[]{far,near}),new LOD(.012f,new[]{far})});lod.RecalculateBounds();PrefabUtility.SaveAsPrefabAsset(prefab,path);PrefabUtility.UnloadPrefabContents(prefab);}
AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);var center=yard.GetComponent<Renderer>().bounds.center;capture.Invoke(null,new object[]{scene,center+new Vector3(90,150,-120),center,"Yatch-Port-Shared-Atlas"});File.WriteAllText("FinalEnvironmentRoadReview/SharedYachtAtlasReport.txt","SUCCESS one texture atlas / one material for Yatch_Port and six docking piers; converted mesh assets="+converted+"; yard vertices/triangles verified unchanged; piers 2 combined renderers near / 1 distant; ASTC6x6 streamed atlas; shader errors="+ShaderUtil.GetShaderMessages(shared.shader).Count(v=>v.severity.ToString()=="Error"));}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/SharedYachtAtlasReport.txt","FAILED "+e);Debug.LogException(e);}}
}
